#!/usr/bin/env python3
"""Generate content/facts-requested.yaml (myAD Content -> myAD Research handoff).

Collects every fact id referenced by a card (fact_refs, verified_only_refs, {fact:<id>}
placeholders, paragraph_facts) or by a desk (desks.yaml fact_refs), adds the six contact
facts <desk-id>.{name,phone,url,address,hours,languages} for every desk, and writes one
entry per id. need/question/value_type/kind/topics/hint come from the hand-written
tables below; ids that hit the fallback are listed on stdout so the tables can be fixed.

Never put a value (number, phone, date, price, desk URL) into this file: the plans are
cited by file and section only.

Usage: python3 content/tools/gen_facts_requested.py [--check|--check-fresh]
  --check        only print the summary, do not write the file.
  --check-fresh  generate in memory and fail if facts-requested.yaml is stale.
"""
from __future__ import annotations

