# Per-id table (hand-written). S = static, L = lookup (address- or household-dependent).
MD, MI, FL, US = "us-fl-miamidade", "us-fl-miami", "us-fl", "us"


def S(need, vt, topics, hint, pub, **kw):
    return dict(need=need, vt=vt, kind="static", topics=topics, hint=hint, pub=pub, **kw)


def L(need, vt, topics, hint, pub, q, endpoint=None, **kw):
    return dict(need=need, vt=vt, kind="lookup", topics=topics, hint=hint, pub=pub, q=q, endpoint=endpoint, **kw)


