DESK_FIELD_NEED = {
    "name": "Official name of {d}, exactly as the agency writes it",
    "phone": "Public phone number for {d}",
    "url": "Official web address for {d}",
    "address": "Street address of {d}",
    "hours": "Opening or phone hours of {d}",
    "languages": "Languages {d} answers in (phone line or counter)",
}


def load(path):
    with open(path, encoding="utf-8") as fh:
        return yaml.safe_load(fh)


def topic_vocab():
    """research/topics.yaml is the authority when present; otherwise the seed list."""
    if not TOPICS_FILE.exists():
        return set(SEED_TOPICS)
    doc = load(TOPICS_FILE)
    items = doc.get("topics", []) if isinstance(doc, dict) else doc
    vocab = set()
    for it in items or []:
        if isinstance(it, str):
            vocab.add(it)
        elif isinstance(it, dict):
            for k in ("id", "tag", "name"):
                if isinstance(it.get(k), str):
                    vocab.add(it[k])
                    break
    return vocab


def strings(obj):
    if isinstance(obj, str):
        yield obj
    elif isinstance(obj, dict):
        for v in obj.values():
            yield from strings(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from strings(v)


def lower_first(s):
    return s[0].lower() + s[1:] if s else s


def fact_topic(topics):
    """The ledger topic is derived only from its requested topic tags."""
    return "immigration" if {"immigration", "tps"} & set(topics or []) else "general"


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--check-fresh", action="store_true")
    ap.add_argument("--output", type=Path, default=OUT,
                    help="generated path (used by CI freshness checks)")
    args = ap.parse_args(argv)

    vocab = topic_vocab()
    tr_path = CONTENT / "topics-requested.yaml"
    pending_tags = {i.get("tag") for i in ((load(tr_path) or {}).get("requested") or []) if isinstance(i, dict)} if tr_path.exists() else set()
    desks = {d["id"]: d for d in (load(CONTENT / "desks.yaml").get("desks") or [])}
    cards = {}
    for p in sorted(glob.glob(str(CONTENT / "cards" / "*.yaml"))):
        c = load(p)
        if isinstance(c, dict) and c.get("id"):
            cards[c["id"]] = c
    lenses = {}
    for p in sorted(glob.glob(str(CONTENT / "lenses" / "*.yaml"))):
        lz = load(p)
        if isinstance(lz, dict) and lz.get("id"):
            lenses[lz["id"]] = lz

    direct = collections.defaultdict(list)  # fid -> cards citing it directly, in card order
    vo_ids = set()
    for cid, c in cards.items():
        refs = list(c.get("fact_refs") or [])
        vo = list(c.get("verified_only_refs") or [])
        vo_ids.update(vo)
        refs += vo
        for key in ("title", "summary", "body"):
            for s in strings(c.get(key)):
                refs += PLACEHOLDER_RE.findall(s)
        for para in c.get("paragraph_facts") or []:
            refs += list(para or [])
        for f in refs:
            if cid not in direct[f]:
                direct[f].append(cid)
    lens_users = collections.defaultdict(list)
    for lid, lz in lenses.items():
        refs = list(lz.get("fact_refs") or []) + [x for s in strings(lz) for x in PLACEHOLDER_RE.findall(s)]
        for f in refs:
            if lid not in lens_users[f]:
                lens_users[f].append(lid)

    enders, actors = collections.defaultdict(list), collections.defaultdict(list)
    for cid, c in cards.items():
        if c.get("desk"):
            enders[c["desk"]].append(cid)
        for a in c.get("actions") or []:
            ad = isinstance(a, dict) and (a.get("desk_id") or (a.get("target") or {}).get("desk_id"))
            if ad and cid not in actors[ad]:
                actors[ad].append(cid)
    desk_refs = {f: did for did, d in desks.items() for f in (d.get("fact_refs") or [])}

    ids = set(direct) | set(desk_refs)

    def ns_desk_of(fid):
        best = None
        for did in desks:
            if fid.startswith(did + ".") and (best is None or len(did) > len(best)):
                best = did
        return best

    entries, fallback, problems = [], [], []
    for fid in sorted(ids):
        pack = fid.split(".", 1)[0]
        ns_desk = ns_desk_of(fid)
        field = fid.rsplit(".", 1)[1]
        is_contact = bool(ns_desk) and fid == f"{ns_desk}.{field}" and field in DESK_FIELDS
        users = list(direct.get(fid, []))
        cards_list = list(users)
        if is_contact:
            for cid in enders.get(ns_desk, []) + actors.get(ns_desk, []):
                if cid not in cards_list:
                    cards_list.append(cid)
        first = (users or (enders.get(ns_desk, []) if ns_desk else []) or cards_list or [None])[0]
        if first is None:
            problems.append(f"{fid}: no card shows it")
            first = sorted(cards)[0]
        if ns_desk:
            desk = ns_desk
        else:
            cnt = collections.Counter(cards[c].get("desk") for c in users if cards[c].get("desk"))
            desk = cnt.most_common(1)[0][0] if cnt else None
            if desk is None:
                problems.append(f"{fid}: no owning desk")
        used_by = [f"card:{c}" for c in users] + [f"lens:{lid}" for lid in lens_users.get(fid, [])]
        if fid in desk_refs:
            used_by.append(f"desk:{desk_refs[fid]}")
        if not used_by and ns_desk:
            used_by = [f"desk:{ns_desk}"]  # extra contact field the desk owns but desks.yaml does not list yet

        note, verified_only, endpoint, unit, q = None, False, None, None, None
        if fid in vo_ids or fid in VO:
            spec = VO.get(fid)
            if spec is None:
                fallback.append(fid)
                spec = dict(need=f"Status date named by {fid}", topics=["immigration"], pub="USCIS / Federal Register / CMS / FL AHCA")
            need, vt, kind, topics, pub, ftype = spec["need"], "date", "static", spec["topics"], spec["pub"], "official"
            hint, pref = VO_HINT, None
            verified_only = True
            note = (f"Status date under the Firstmate hold: {VO_HINT}. Cards carry it only in verified_only_refs; "
                    "the app shows it only when the ledger status is verified.")
            q = f"What exact date does the primary source give for: {lower_first(need)}? Quote the notice and link the primary page."
        elif is_contact:
            d = desks[ns_desk]
            dname = (d.get("name") or {}).get("en", ns_desk)
            kind = d.get("contact_kind", "static")
            vt = DESK_FIELD_TYPES[field]
            need = DESK_FIELD_NEED[field].format(d=dname if kind == "static" else f"{dname} (the one nearest the pin)")
            topics = list(d.get("topics") or []) + ["desk"]
            hk = DESK_HINTS.get(ns_desk)
            if hk:
                hint, pref = H[hk][0] + f"; the {field} itself comes from the desk's own official page", H[hk][1]
            else:
                hint, pref = f"not named in the plans; the desk's own official page ({dname})", None
            pub = dname
            ftype = "adapter-table" if kind == "lookup" else "official"
            q = (f"For a pin, which one is nearest ({dname}), and what is its {field}?" if kind == "lookup"
                 else f"What is the {field} of {dname}, as the agency publishes it on its own page?")
        elif fid in F:
            s = F[fid]
            need, vt, kind = s["need"], s["vt"], s["kind"]
            topics = list(s["topics"])
            hint, pref = H[s["hint"]]
            pub = s["pub"]
            ftype = s.get("ftype", "adapter-table" if kind == "lookup" else "official")
            unit, note = s.get("unit"), s.get("note")
            endpoint = s.get("endpoint") if kind == "lookup" else None
            q = s.get("q") or (f"{JURIS[pack]}: {lower_first(need)}. What does the primary source ({pub}) say, "
                               "in its own words, and on which page?")
        else:  # fallback: listed on stdout so the table gets fixed
            fallback.append(fid)
            words = field.replace("-", " ")
            need = f"{words} ({fid.split('.')[1]}), {JURIS[pack]}"
            vt, kind, topics, pub, ftype = "text", "static", [], "to be identified by Research", "official"
            hint, pref = "not named in the plans; Research to find the primary source", None
            q = f"What is the {words} for {JURIS[pack]}, per the primary source?"

        if fid in F and F[fid].get("desk"):
            # table override: the desk the ledger fact names (e.g. the fee is charged at the county
            # Tax Collector, not by FLHSMV, although the id sits in the FLHSMV namespace)
            desk = F[fid]["desk"]
        if ".groceries." in fid:
            note = GROCERY_NOTE
        # seed/topics.yaml tags only; a verified-only benefits date may also carry the benefits tag
        # ("health") while it is pending in content/topics-requested.yaml.
        allowed = vocab | (BENEFITS_TAGS & pending_tags if verified_only else set())
        topics = [t for t in dict.fromkeys(topics) if t in allowed]
        if vt not in VALUE_TYPES:
            problems.append(f"{fid}: bad value_type {vt}")
        if vt in ("money", "quantity") and not unit:
            problems.append(f"{fid}: {vt} without unit")
        if is_contact:
            topic = "immigration" if desks[ns_desk].get("immigration") else "general"
        else:
            topic = fact_topic(topics)

        e = {"id": fid, "card": first, "cards": cards_list, "need": need, "hint": hint,
             "kind": kind, "value_type": vt}
        if unit:
            e["unit"] = unit
        e.update({"topics": topics, "topic": topic, "desk": desk})
        if kind == "lookup" and q:
            e["question"] = q
        if kind == "lookup" and endpoint:
            e["endpoint"] = endpoint
        e.update({"fact_type": ftype, "status": "requested", "used_by": used_by, "plan_text": None})
        if pref and pref[0] in PLAN_REF_PLANS:
            e["plan_ref"] = {"plan": pref[0], "section": pref[1]}
            e["content_added_reason"] = "plan_text left empty on purpose: plan values are never copied here; see hint and plan_ref"
        else:
            who = f"desk {desk}" if is_contact else f"card {first}"
            e["content_added_reason"] = f"no plan_text copied (values stay out of this file); requested because {who} needs it"
        e["source"] = {"publisher": pub, "url": None}
        if verified_only:
            e["verified_only"] = True
        if note:
            e["note"] = note
        entries.append(e)

    body = yaml.safe_dump({"requested": entries}, sort_keys=False, allow_unicode=True, width=1000)
    generated = HEADER + body
    if args.check_fresh:
        target = args.output
        if not target.exists() or target.read_text(encoding="utf-8") != generated:
            print(f"STALE: {target}")
            return 1
    elif not args.check:
        args.output.write_text(generated, encoding="utf-8")

    c_kind = collections.Counter(e["kind"] for e in entries)
    c_vt = collections.Counter(e["value_type"] for e in entries)
    contact = [e for e in entries if ns_desk_of(e["id"]) and e["id"] == f"{ns_desk_of(e['id'])}.{e['id'].rsplit('.', 1)[1]}"
               and e["id"].rsplit(".", 1)[1] in DESK_FIELDS]
    extra = [e["id"] for e in contact if e["id"] not in desk_refs and not direct.get(e["id"])]
    print(f"entries={len(entries)} kind={dict(c_kind)} desk_contact_facts={len(contact)} (not in desks.yaml fact_refs: {len(extra)})")
    print(f"value_type={dict(sorted(c_vt.items()))}")
    print(f"topic_field={dict(collections.Counter(e['topic'] for e in entries))} no_topic_tags={sum(1 for e in entries if not e['topics'])}")
    print(f"verified_only={sorted(e['id'] for e in entries if e.get('verified_only'))}")
    print(f"fallback={fallback}")
    print(f"problems={problems[:20]}")
    print(f"table_ids_not_referenced={sorted(set(F) - ids)}")
    print(f"lens_only_ids={sorted(set(lens_users) - ids)}")
    print(f"wrote={'no (--check/--check-fresh)' if (args.check or args.check_fresh) else args.output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
